Here is the commit message:
trivial: Fix a fuzzer-detected read-overflow

This was introduced in e91c88...

Here is the root cause:
The bug was caused by a read-overflow due to incorrect handling of the size of the data being processed. Specifically, the original code did not properly set the size of the buffer (`bufsz`) before using it, which could lead to accessing memory beyond the allocated size when calculating the checksum. This oversight could result in reading invalid memory, leading to potential crashes or undefined behavior.

Here is the patch:

 static gboolean
 fu_efi_firmware_volume_parse(FuFirmware *firmware,
 			     GBytes *fw,
 			     gsize offset,
 			     FwupdInstallFlags flags,
 			     GError **error)
 {
 	FuEfiFirmwareVolume *self = FU_EFI_FIRMWARE_VOLUME(firmware);
 	FuEfiFirmwareVolumePrivate *priv = GET_PRIVATE(self);
 	gsize blockmap_sz = 0;
-	gsize bufsz = 0;
+	gsize bufsz = g_bytes_get_size(fw);
 	guint16 hdr_length = 0;
 	guint32 attrs = 0;
 	guint64 fv_length = 0;
 	guint8 alignment;
-	const guint8 *buf = g_bytes_get_data(fw, &bufsz);
 	g_autofree gchar *guid_str = NULL;
 	g_autoptr(GBytes) blob = NULL;
 	g_autoptr(GByteArray) st_hdr = NULL;

 	/* parse */
 	st_hdr = fu_struct_efi_volume_parse_bytes(fw, offset, error);
 	if (st_hdr == NULL)
 		return FALSE;

 	/* guid */
 	guid_str = fwupd_guid_to_string(fu_struct_efi_volume_get_guid(st_hdr),
 					FWUPD_GUID_FLAG_MIXED_ENDIAN);
 	g_debug("volume GUID: %s [%s]", guid_str, fu_efi_guid_to_name(guid_str));

 	/* length */
 	fv_length = fu_struct_efi_volume_get_length(st_hdr);
 	if (fv_length == 0x0) {
 		g_set_error_literal(error,
 				    FWUPD_ERROR,
 				    FWUPD_ERROR_INTERNAL,
 				    "invalid volume length");
 		return FALSE;
 	}
 	fu_firmware_set_size(firmware, fv_length);
 	attrs = fu_struct_efi_volume_get_attrs(st_hdr);
 	alignment = (attrs & 0x00ff0000) >> 16;
 	if (alignment > FU_FIRMWARE_ALIGNMENT_2G) {
 		g_set_error(error,
 			    G_IO_ERROR,
 			    G_IO_ERROR_NOT_FOUND,
 			    "0x%x invalid, maximum is 0x%x",
 			    (guint)alignment,
 			    (guint)FU_FIRMWARE_ALIGNMENT_2G);
 		return FALSE;
 	}
 	fu_firmware_set_alignment(firmware, alignment);
 	priv->attrs = attrs & 0xffff;
 	hdr_length = fu_struct_efi_volume_get_hdr_len(st_hdr);
 	if (hdr_length < st_hdr->len || hdr_length > fv_length || hdr_length > bufsz ||
 	    hdr_length % 2 != 0) {
 		g_set_error(error,
 			    FWUPD_ERROR,
 			    FWUPD_ERROR_INTERNAL,
 			    "invalid volume header length 0x%x",
 			    (guint)hdr_length);
 		return FALSE;
 	}

 	/* verify checksum */
 	if ((flags & FWUPD_INSTALL_FLAG_IGNORE_CHECKSUM) == 0) {
-		guint16 checksum_verify = fu_sum16w(buf + offset, hdr_length, G_LITTLE_ENDIAN);
+		guint16 checksum_verify;
+		g_autoptr(GBytes) blob_hdr = NULL;
+
+		blob_hdr = fu_bytes_new_offset(fw, offset, hdr_length, error);
+		if (blob_hdr == NULL)
+			return FALSE;
+		checksum_verify = fu_sum16w_bytes(blob_hdr, G_LITTLE_ENDIAN);
 		if (checksum_verify != 0) {
 			g_set_error(error,
 				    FWUPD_ERROR,
 				    FWUPD_ERROR_INVALID_FILE,
 				    "checksum invalid, got %02x, expected %02x",
 				    checksum_verify,
 				    fu_struct_efi_volume_get_checksum(st_hdr));
 			return FALSE;
 		}
 	}

 	/* add image */
 	blob = fu_bytes_new_offset(fw, offset + hdr_length, fv_length - hdr_length, error);
 	if (blob == NULL)
 		return FALSE;
 	fu_firmware_set_offset(firmware, offset);
 	fu_firmware_set_id(firmware, guid_str);
 	fu_firmware_set_size(firmware, fv_length);

 	/* parse, which might cascade and do something like FFS2 */
 	if (g_strcmp0(guid_str, FU_EFI_FIRMWARE_VOLUME_GUID_FFS2) == 0 ||
 	    g_strcmp0(guid_str, FU_EFI_FIRMWARE_VOLUME_GUID_FFS3) == 0) {
 		g_autoptr(FuFirmware) img = fu_efi_firmware_filesystem_new();
 		fu_firmware_set_alignment(img, fu_firmware_get_alignment(firmware));
 		if (!fu_firmware_parse(img, blob, flags | FWUPD_INSTALL_FLAG_NO_SEARCH, error))
 			return FALSE;
 		fu_firmware_add_image(firmware, img);
 	} else {
 		fu_firmware_set_bytes(firmware, blob);
 	}

 	/* skip the blockmap */
 	offset += st_hdr->len;
 	while (offset < bufsz) {
 		guint32 num_blocks;
 		guint32 length;
 		g_autoptr(GByteArray) st_blk = NULL;
 		st_blk = fu_struct_efi_volume_block_map_parse_bytes(fw, offset, error);
 		if (st_blk == NULL)
 			return FALSE;
 		num_blocks = fu_struct_efi_volume_block_map_get_num_blocks(st_blk);
 		length = fu_struct_efi_volume_block_map_get_length(st_blk);
 		offset += st_blk->len;
 		if (num_blocks == 0x0 && length == 0x0)
 			break;
 		blockmap_sz += (gsize)num_blocks * (gsize)length;
 	}
 	if (blockmap_sz < (gsize)fv_length) {
 		g_set_error_literal(error,
 				    FWUPD_ERROR,
 				    FWUPD_ERROR_INTERNAL,
 				    "blocks allocated is less than volume length");
 		return FALSE;
 	}

 	/* success */
 	return TRUE;
 }



